#include "quake/frame3d.hpp"
#include "quake/newmark.hpp"
#include "quake/calibration.hpp"
#include <iomanip>
#include <iostream>
#include <vector>
using namespace quake;
static int nid(int s,int ix,int iy){return 10000*s+100*ix+iy;}
static IMKPeakOrientedParams hinge_params(){IMKPeakOrientedParams p;p.Ke=50000;p.posUp=p.negUp=.004;p.posUpc=p.negUpc=.018;p.posUu=p.negUu=.055;p.posFy=p.negFy=8;p.posFcapFy=p.negFcapFy=1.12;p.posFresFy=p.negFresFy=.20;p.lambdaS=.08;p.lambdaC=.10;p.lambdaA=.12;p.lambdaK=.10;p.cS=p.cC=p.cA=p.cK=1.0;p.Dpos=p.Dneg=1.0;return p;}
static CompiledFrame3D make_model(int stories,int nx,int ny){Frame3DBuilder b;constexpr double h=3.5,L=6,E=25000,G=10000;int eid=1,sid=1,did=700000;const int nc=(nx+1)*(ny+1);for(int s=0;s<=stories;++s)for(int ix=0;ix<=nx;++ix)for(int iy=0;iy<=ny;++iy){double m=s?1.0/nc:0;b.add_node(nid(s,ix,iy),ix*L,iy*L,s*h,m,m,.05*m);if(!s)b.fix(nid(s,ix,iy));}auto hp=hinge_params();for(int s=1;s<=stories;++s){for(int ix=0;ix<=nx;++ix)for(int iy=0;iy<=ny;++iy)b.add_elastic_frame(eid++,nid(s-1,ix,iy),nid(s,ix,iy),E,G,2,.3,.55,.55,1,0,0,8*(stories-s+1));for(int ix=0;ix<nx;++ix)for(int iy=0;iy<=ny;++iy){int jl=nid(s,ix,iy),jr=nid(s,ix+1,iy),dl=did++,dr=did++;b.add_node(dl,ix*L,iy*L,s*h);b.add_node(dr,(ix+1)*L,iy*L,s*h);for(auto d:{Dof3D::UX,Dof3D::UY,Dof3D::UZ,Dof3D::RX,Dof3D::RZ}){b.equal_dof(jl,dl,d);b.equal_dof(jr,dr,d);}b.add_elastic_frame(eid++,dl,dr,E,G,1.5,.2,.35,.35,0,1,0);b.add_imk_peak_oriented_spring(sid++,jl,Dof3D::RY,dl,Dof3D::RY,hp);b.add_imk_peak_oriented_spring(sid++,jr,Dof3D::RY,dr,Dof3D::RY,hp);}for(int ix=0;ix<=nx;++ix)for(int iy=0;iy<ny;++iy){int jl=nid(s,ix,iy),jr=nid(s,ix,iy+1),dl=did++,dr=did++;b.add_node(dl,ix*L,iy*L,s*h);b.add_node(dr,ix*L,(iy+1)*L,s*h);for(auto d:{Dof3D::UX,Dof3D::UY,Dof3D::UZ,Dof3D::RY,Dof3D::RZ}){b.equal_dof(jl,dl,d);b.equal_dof(jr,dr,d);}b.add_elastic_frame(eid++,dl,dr,E,G,1.5,.2,.35,.35,1,0,0);b.add_imk_peak_oriented_spring(sid++,jl,Dof3D::RX,dl,Dof3D::RX,hp);b.add_imk_peak_oriented_spring(sid++,jr,Dof3D::RX,dr,Dof3D::RX,hp);}}b.set_rayleigh(.02,.0005);b.set_ground_direction(Dof3D::UX);b.set_response(nid(stories,0,0),Dof3D::UX);std::vector<int>sn;for(int s=1;s<=stories;++s)sn.push_back(nid(s,0,0));b.set_story_nodes(std::move(sn),Dof3D::UX);return b.compile();}
int main(int argc,char**argv){int stories=argc>1?std::stoi(argv[1]):10,nx=argc>2?std::stoi(argv[2]):2,ny=argc>3?std::stoi(argv[3]):2,steps=argc>4?std::stoi(argv[4]):400;double amp=argc>5?std::stod(argv[5]):2.0,dt=.005;auto m=make_model(stories,nx,ny);auto gm=synthetic_ground_motion(steps,dt,amp);AnalysisResult full,same,wood;bool robust=false;try{full=run_newmark(m,gm,dt,LinearStrategy::FullFactorization,1e-8,45);same=run_newmark(m,gm,dt,LinearStrategy::SamePatternRefactorization,1e-8,45);wood=run_newmark(m,gm,dt,LinearStrategy::Woodbury,1e-8,45);}catch(const std::exception&){robust=true;RobustNewmarkOptions o;o.max_iterations=35;o.max_subdivisions=4;o.direct_rank_fraction=.30;full=run_newmark_robust(m,gm,dt,LinearStrategy::FullFactorization,o);same=run_newmark_robust(m,gm,dt,LinearStrategy::SamePatternRefactorization,o);wood=run_newmark_robust(m,gm,dt,LinearStrategy::Woodbury,o);}AnalysisResult adaptive;SolverCalibrationResult cal;bool ran_adaptive=false;if(!robust){cal=calibrate_solver_crossover(m,dt,{},3);PreparedAdaptiveNewmark pa(m,dt,cal.recommended_woodbury_rank_limit);adaptive=pa.run(gm,1e-8,45);ran_adaptive=true;}auto&s=wood.stats;auto frac=[&](std::size_t x){return s.nonlinear_component_evaluations?double(x)/s.nonlinear_component_evaluations:0.0;};std::cout<<std::fixed<<std::setprecision(6)<<"stories="<<stories<<" bays="<<nx<<"x"<<ny<<" dof="<<m.dof()<<" imk_hinges="<<m.nonlinear_count()<<" state_size="<<m.nonlinear_state_size()<<" steps="<<steps<<" amp="<<amp<<" robust="<<robust<<"\n"<<"full_seconds="<<full.stats.elapsed_seconds<<" same_seconds="<<same.stats.elapsed_seconds<<" woodbury_seconds="<<wood.stats.elapsed_seconds<<" speedup_vs_full="<<full.stats.elapsed_seconds/wood.stats.elapsed_seconds<<"x speedup_vs_same="<<same.stats.elapsed_seconds/wood.stats.elapsed_seconds<<"x\n"<<"newton_full="<<full.stats.newton_iterations<<" newton_same="<<same.stats.newton_iterations<<" newton_wood="<<wood.stats.newton_iterations<<" peak_full="<<full.stats.max_roof_abs<<" peak_wood="<<wood.stats.max_roof_abs<<"\n"<<(ran_adaptive?(std::string("calibration_seconds=")+std::to_string(cal.elapsed_seconds)+" calibrated_rank_limit="+std::to_string(cal.recommended_woodbury_rank_limit)+" adaptive_seconds="+std::to_string(adaptive.stats.elapsed_seconds)+" adaptive_wood_solves="+std::to_string(adaptive.stats.adaptive_woodbury_solves)+" adaptive_direct_solves="+std::to_string(adaptive.stats.adaptive_direct_solves)+"\n"):std::string())<<"component_evals="<<s.nonlinear_component_evaluations<<" fast_path="<<s.nonlinear_fast_path_evaluations<<" fast_fraction="<<frac(s.nonlinear_fast_path_evaluations)<<" full_state="<<s.nonlinear_full_state_evaluations<<" full_fraction="<<frac(s.nonlinear_full_state_evaluations)<<"\n"<<"transitions="<<s.nonlinear_transition_events<<" reversals="<<s.nonlinear_reversal_events<<" deterioration="<<s.nonlinear_deterioration_events<<" failures="<<s.nonlinear_failure_events<<" max_rank="<<s.max_active_rank<<" subdivisions="<<s.subdivided_steps<<"\n";}
